suppressMessages(library(dplyr))
h <- readRDS("data/federal_elections/county_level/final/federal_cty_harm.rds")
u <- readRDS("data/federal_elections/county_level/final/federal_cty_unharm.rds")
cat("dup:", sum(duplicated(h[,c("county_code","election_year")])), " nchar:"); print(table(nchar(h$county_code)))
print(table(h$election_year)); cat("state mismatch:", sum(substr(h$county_code,1,2)!=h$state),"\n")
cat("NA counts: elig",sum(is.na(h$eligible_voters)),"nv",sum(is.na(h$number_voters)),"turn",sum(is.na(h$turnout)),"area",sum(is.na(h$area)),"pop",sum(is.na(h$population)),"\n")
print(summary(h$turnout)); print(summary(h$total_votes/h$valid_votes))
print(table(h$flag_unsuccessful_naive_merge, useNA="a"))
print(h %>% group_by(election_year) %>% summarise(n=n(), elig=sum(eligible_voters,na.rm=T), nv=sum(number_voters,na.rm=T), valid=sum(valid_votes,na.rm=T), turn=nv/elig, tvr=sum(total_votes,na.rm=T)/valid) %>% left_join(u %>% group_by(election_year=year) %>% summarise(elig_u=sum(eligible_voters), nv_u=sum(number_voters), valid_u=sum(valid_votes))) %>% mutate(rel_elig=elig/elig_u-1, rel_nv=nv/nv_u-1, rel_val=valid/valid_u-1) %>% as.data.frame)
cat("turnout recompute mism:", sum(abs(h$turnout-h$number_voters/h$eligible_voters)>1e-6,na.rm=T),"\n")
print(h %>% filter(turnout>1|turnout<0.4|is.na(turnout)) %>% select(county_code,election_year,turnout,eligible_voters,number_voters) %>% head(20) %>% as.data.frame)
print(summary(h$area)); print(summary(h$population))
cat("AfD 2013 cdu 1990 etc. share range\n")
S <- as.matrix(h[,"cdu":"zentrum" |> deparse() |> (\(x) 9:118)()]) 
